//! Platform-agnostic client trait.
//! (Generated by v0.6.0 Step 3 Phase 1)
//!
//! Every platform backend (GitHub, GitLab, Gitea, …) implements
//! [`PlatformClient`] so the App layer drives one async interface.
//! [`crate::github::GithubClient`] is the M2 single-backend implementation.

use async_trait::async_trait;

use crate::github::models::{
    CheckSummary, IssueDetail, IssueSummary, NotificationSummary, PrDetail, PrSummary,
};
use crate::platform::error::PlatformError;

/// Async, object-safe interface every platform client implements.
#[async_trait]
pub trait PlatformClient: Send + Sync {
    /// Open PRs (first page, 100).
    async fn list_pulls(&self) -> Result<Vec<PrSummary>, PlatformError>;

    /// PR detail + head-commit checks.
    async fn get_pull(&self, number: u64) -> Result<PrDetail, PlatformError>;

    /// Check runs for a commit SHA.
    async fn list_checks(&self, sha: &str) -> Result<Vec<CheckSummary>, PlatformError>;

    /// Open issues excluding PRs.
    async fn list_issues(&self) -> Result<Vec<IssueSummary>, PlatformError>;

    /// Single issue detail.
    async fn get_issue(&self, number: u64) -> Result<IssueDetail, PlatformError>;

    /// Repo-scoped notifications.
    async fn list_notifications(&self) -> Result<Vec<NotificationSummary>, PlatformError>;
}

use crate::platform::gitea::GiteaClient;
use crate::platform::gitlab::GitLabClient;
use crate::platform::remote::{PlatformKind, PlatformRemote};

/// Build the platform-specific [`PlatformClient`] for a parsed remote URL.
pub fn build_client(remote: &PlatformRemote) -> Result<Box<dyn PlatformClient>, PlatformError> {
    match remote.kind {
        PlatformKind::GitHub | PlatformKind::SelfHosted => {
            let client = crate::github::GithubClient::new(&remote.owner, &remote.repo)?;
            Ok(Box::new(client))
        }
        PlatformKind::Gitea => Ok(Box::new(GiteaClient::new(remote)?)),
        PlatformKind::GitLab => Ok(Box::new(GitLabClient::new(remote)?)),
    }
}
